from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
print('sheets:', wb.sheetnames)
for wsname in ['Task','Data']:
    ws=wb[wsname]
    print(wsname, 'max_row', ws.max_row, 'max_col', ws.max_column)
print('\nTask D:L rows 10-50 values:')
ws=wb['Task']
for r in range(10,51):
    vals=[]
    for c in range(1,13):
        v=ws.cell(r,c).value
        if v is not None:
            vals.append(f'{get_column_letter(c)}{r}={v!r}')
    if vals:
        print('; '.join(vals))
print('\nData rows 18-40 values nonempty:')
ws=wb['Data']
for r in range(18,41):
    vals=[]
    for c in range(1,ws.max_column+1):
        v=ws.cell(r,c).value
        if v is not None:
            vals.append(f'{get_column_letter(c)}{r}={v!r}')
    if vals:
        print('; '.join(vals))
